use vstd::prelude::*;

verus! {

    /// Returns the index of the first (leftmost) minimum element in a nonempty Vec<i8>.
    /// 
    /// Specification:
    ///   - The result is in‐bounds.
    ///   - a[result] ≤ a[j] for every j in the array.
    ///   - For every j < result, a[j] > a[result].
    pub fn argmin(a: Vec<i8>) -> usize
        ensures |ret: usize|
            ret < a.len()
            && forall(|j: usize| j < a.len() ==> a[ret] <= a[j])
            && forall(|j: usize| j < ret      ==> a[j] >  a[ret])
    {
        let n = a.len();
        // The problem assumes a is nonempty.
        assert(n > 0);

        // min_idx will always satisfy 0 <= min_idx < n
        // and it points to the first minimum among a[0..i).
        let mut min_idx: usize = 0;
        // i ranges from 1 ..= n
        let mut i: usize = 1;

        while i < n {
            // Invariants maintain that among the first i elements
            // min_idx is the first minimal element, and that
            // elements before min_idx are strictly greater.
            invariant i <= n;
            invariant min_idx < n;
            invariant forall(|j: usize| j < i         ==> a[min_idx] <= a[j]);
            invariant forall(|j: usize| j < min_idx  ==> a[j] >  a[min_idx]);
            decreases n - i;

            if a[i] < a[min_idx] {
                // We are about to set min_idx = i.  We must re‐establish
                // the two invariants for the new min_idx.
                //
                // 1) For all j < i, a[i] <= a[j]:
                //    From old invariant: a[old_min_idx] <= a[j], and
                //    from a[i] < a[old_min_idx], we get a[i] < a[j],
                //    hence a[i] <= a[j].
                //
                // 2) For all j < i, a[j] > a[i]:
                //    From old invariant: a[old_min_idx] <= a[j], and
                //    from a[i] < a[old_min_idx], we get a[j] > a[i].
                assert(forall(|j: usize| j < i ==> a[i] <= a[j]));
                assert(forall(|j: usize| j < i ==> a[j] >  a[i]));

                min_idx = i;
            } else {
                // If we do not update, we must still show
                // a[min_idx] <= a[i] to extend the "min among first i+1"
                // invariant.
                assert(a[min_idx] <= a[i]);
            }

            i += 1;
        }

        // At the end i == n, so min_idx is the first global minimum.
        min_idx
    }

}